import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry min_reduce_dim_f32(
    .param .u64 in_ptr_param,
    .param .u64 out_ptr_param,
    .param .u32 dim_param,
    .param .u32 size0_param,
    .param .u32 size1_param,
    .param .u32 size2_param,
    .param .u64 stride0_param,
    .param .u64 stride1_param,
    .param .u64 stride2_param
)
{
    .reg .pred %p0, %p1, %p2, %p3;
    .reg .b32 %r_dim, %r_tmp;
    .reg .b32 %r_sz0, %r_sz1, %r_sz2;
    .reg .b64 %in_ptr, %out_ptr;
    .reg .b64 %st0, %st1, %st2;
    .reg .b64 %n0_64, %n1_64, %n2_64, %sizeR_64, %out_numel, %prod;
    .reg .b32 %r_tid, %r_bdim, %r_cta, %r_gdim;
    .reg .b64 %idx, %step, %tmp64, %q, %rem;
    .reg .f32 %f_min, %f_val;
    .reg .b64 %i0, %i1, %i2, %iR, %k_end;
    .reg .b64 %base_off_elems, %elem_off, %addr, %out_addr;
    // Load parameters
    ld.param.u64 %in_ptr, [in_ptr_param];
    ld.param.u64 %out_ptr, [out_ptr_param];
    ld.param.u32 %r_dim, [dim_param];
    ld.param.u32 %r_sz0, [size0_param];
    ld.param.u32 %r_sz1, [size1_param];
    ld.param.u32 %r_sz2, [size2_param];
    ld.param.u64 %st0, [stride0_param];
    ld.param.u64 %st1, [stride1_param];
    ld.param.u64 %st2, [stride2_param];
    // Convert sizes to 64-bit
    cvt.u64.u32 %n0_64, %r_sz0;
    cvt.u64.u32 %n1_64, %r_sz1;
    cvt.u64.u32 %n2_64, %r_sz2;
    // Select sizeR based on dim
    mov.u64 %sizeR_64, %n2_64;
    setp.eq.u32 %p0, %r_dim, 0;
    selp.u64 %sizeR_64, %n0_64, %sizeR_64, %p0;
    setp.eq.u32 %p1, %r_dim, 1;
    selp.u64 %sizeR_64, %n1_64, %sizeR_64, %p1;
    // out_numel = (n0*n1*n2)/sizeR
    mul.lo.u64 %prod, %n0_64, %n1_64;
    mul.lo.u64 %prod, %prod, %n2_64;
    div.u64 %out_numel, %prod, %sizeR_64;
    // Thread indexing and grid-stride setup
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_bdim, %ntid.x;
    mov.u32 %r_cta, %ctaid.x;
    mov.u32 %r_gdim, %nctaid.x;
    mad.lo.u32 %r_tmp, %r_cta, %r_bdim, %r_tid; // idx0 = blockIdx.x*blockDim.x + threadIdx.x
    cvt.u64.u32 %idx, %r_tmp;
    mul.lo.u32 %r_tmp, %r_bdim, %r_gdim; // step = blockDim.x * gridDim.x
    cvt.u64.u32 %step, %r_tmp;
LOOP_START:
    setp.ge.u64 %p2, %idx, %out_numel;
    @%p2 bra LOOP_END;
    // Initialize min accumulator to +inf
    mov.b32 %f_min, 0x7f800000;
    // Default indices to 0
    mov.u64 %i0, 0;
    mov.u64 %i1, 0;
    mov.u64 %i2, 0;
    // Branch to the dim-specific path
    setp.eq.u32 %p0, %r_dim, 0;
    @!%p0 bra DIM1;
    // dim == 0: output dims (n1, n2) => i1 = idx / n2; i2 = idx % n2
    div.u64 %q, %idx, %n2_64;
    mul.lo.u64 %tmp64, %q, %n2_64;
    sub.u64 %rem, %idx, %tmp64;
    mov.u64 %i1, %q;
    mov.u64 %i2, %rem;
    // base offset in elements: i1*st1 + i2*st2
    mul.lo.u64 %base_off_elems, %i1, %st1;
    mul.lo.u64 %tmp64, %i2, %st2;
    add.u64 %base_off_elems, %base_off_elems, %tmp64;
    mov.u64 %k_end, %n0_64; // reduce over n0
    mov.u64 %iR, 0;
REDUCE_LOOP_R0:
    setp.ge.u64 %p3, %iR, %k_end;
    @%p3 bra REDUCE_DONE_R0;
    mul.lo.u64 %elem_off, %iR, %st0;
    add.u64 %elem_off, %elem_off, %base_off_elems;
    shl.b64 %addr, %elem_off, 2; // *4 bytes (f32)
    add.u64 %addr, %addr, %in_ptr;
    ld.global.f32 %f_val, [%addr];
    min.f32 %f_min, %f_min, %f_val;
    add.u64 %iR, %iR, 1;
    bra REDUCE_LOOP_R0;
REDUCE_DONE_R0:
    bra AFTER_REDUCE;
DIM1:
    setp.eq.u32 %p0, %r_dim, 1;
    @!%p0 bra DIM2;
    // dim == 1: output dims (n0, n2) => i0 = idx / n2; i2 = idx % n2
    div.u64 %q, %idx, %n2_64;
    mul.lo.u64 %tmp64, %q, %n2_64;
    sub.u64 %rem, %idx, %tmp64;
    mov.u64 %i0, %q;
    mov.u64 %i2, %rem;
    // base offset in elements: i0*st0 + i2*st2
    mul.lo.u64 %base_off_elems, %i0, %st0;
    mul.lo.u64 %tmp64, %i2, %st2;
    add.u64 %base_off_elems, %base_off_elems, %tmp64;
    mov.u64 %k_end, %n1_64; // reduce over n1
    mov.u64 %iR, 0;
REDUCE_LOOP_R1:
    setp.ge.u64 %p3, %iR, %k_end;
    @%p3 bra REDUCE_DONE_R1;
    mul.lo.u64 %elem_off, %iR, %st1;
    add.u64 %elem_off, %elem_off, %base_off_elems;
    shl.b64 %addr, %elem_off, 2; // *4 bytes
    add.u64 %addr, %addr, %in_ptr;
    ld.global.f32 %f_val, [%addr];
    min.f32 %f_min, %f_min, %f_val;
    add.u64 %iR, %iR, 1;
    bra REDUCE_LOOP_R1;
REDUCE_DONE_R1:
    bra AFTER_REDUCE;
DIM2:
    // dim == 2: output dims (n0, n1) => i0 = idx / n1; i1 = idx % n1
    div.u64 %q, %idx, %n1_64;
    mul.lo.u64 %tmp64, %q, %n1_64;
    sub.u64 %rem, %idx, %tmp64;
    mov.u64 %i0, %q;
    mov.u64 %i1, %rem;
    // base offset in elements: i0*st0 + i1*st1
    mul.lo.u64 %base_off_elems, %i0, %st0;
    mul.lo.u64 %tmp64, %i1, %st1;
    add.u64 %base_off_elems, %base_off_elems, %tmp64;
    mov.u64 %k_end, %n2_64; // reduce over n2
    mov.u64 %iR, 0;
REDUCE_LOOP_R2:
    setp.ge.u64 %p3, %iR, %k_end;
    @%p3 bra REDUCE_DONE_R2;
    mul.lo.u64 %elem_off, %iR, %st2;
    add.u64 %elem_off, %elem_off, %base_off_elems;
    shl.b64 %addr, %elem_off, 2; // *4 bytes
    add.u64 %addr, %addr, %in_ptr;
    ld.global.f32 %f_val, [%addr];
    min.f32 %f_min, %f_min, %f_val;
    add.u64 %iR, %iR, 1;
    bra REDUCE_LOOP_R2;
REDUCE_DONE_R2:
AFTER_REDUCE:
    // Store result to output (contiguous)
    shl.b64 %out_addr, %idx, 2; // *4 bytes
    add.u64 %out_addr, %out_addr, %out_ptr;
    st.global.f32 [%out_addr], %f_min;
    // Next element
    add.u64 %idx, %idx, %step;
    bra LOOP_START;
LOOP_END:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("min_reduce_dim_f32")

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("Input must be a CUDA tensor")
        if x.dtype != torch.float32:
            raise RuntimeError("Only float32 tensors are supported")
        if x.dim() != 3:
            raise RuntimeError("Only 3D tensors are supported")
        sizes = list(x.size())
        strides = list(x.stride())
        dim = self.dim
        if dim < 0:
            dim += 3
        if dim < 0 or dim > 2:
            raise RuntimeError("Invalid reduction dimension")
        if sizes[dim] == 0:
            raise RuntimeError("Expected reduction dim to have non-zero size")

        out_sizes = [sizes[i] for i in range(3) if i != dim]
        out = torch.empty(out_sizes, device=x.device, dtype=x.dtype)

        module = _get_ptx_module()

        out_numel = out.numel()
        block_x = 256
        grid_x = max(1, min(65535, (out_numel + block_x - 1) // block_x))

        module.launch(
            "min_reduce_dim_f32",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x,
                out,
                u32(int(dim)),
                u32(int(sizes[0])),
                u32(int(sizes[1])),
                u32(int(sizes[2])),
                u64(int(strides[0])),
                u64(int(strides[1])),
                u64(int(strides[2])),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

